using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.LoyaltyDiscount;

public sealed class CalculatePayableTotalAcceptanceTests
{
    [Theory]
    [InlineData(LoyaltyTier.Green, 4_999, 4_750)]    // 5%, discount 249.95 -> 249
    [InlineData(LoyaltyTier.Green, 5_000, 4_700)]    // 50.00 enters +1 band
    [InlineData(LoyaltyTier.Gold, 10_000, 9_200)]
    [InlineData(LoyaltyTier.Green, 19_999, 18_800)]  // 6%, 1199.94 -> 1199
    [InlineData(LoyaltyTier.Green, 20_000, 18_400)]  // 200.00 enters +3 band
    [InlineData(LoyaltyTier.Gold, 20_000, 18_000)]   // 10%
    [InlineData(LoyaltyTier.Platinum, 20_000, 18_000)] // 12% capped at 10
    [InlineData(LoyaltyTier.Platinum, 5_000, 4_500)]  // 10%
    [InlineData(LoyaltyTier.Platinum, 1_999, 1_820)]  // 9%, 179.91 -> 179
    [InlineData(LoyaltyTier.Gold, 0, 0)]
    public void CustomersPayTheApprovedLoyaltyTotal(LoyaltyTier loyaltyTier, int subtotalCents, int expectedPayableCents)
    {
        var payable = new CalculatePayableTotal().For(subtotalCents, loyaltyTier);

        Assert.Equal(expectedPayableCents, payable);
    }
}
E
